#include "common.hpp"
struct Entry {std::string source,value;size_t line;};
std::string decode_value(std::string raw,size_t line,Report&r){raw=trim(raw);if(raw.empty())return "";if(raw[0]=='"'||raw[0]=='\''){char quote=raw[0];std::string out;bool closed=false;size_t i=1;for(;i<raw.size();++i){char c=raw[i];if(c==quote){closed=true;++i;break;}if(c=='\\'&&quote=='"'){if(++i>=raw.size()){r.error(line,"","Dangling escape in quoted value");return "";}switch(raw[i]){case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case '\\':out+='\\';break;case '"':out+='"';break;default:r.error(line,"","Unsupported quoted escape; use \\\\ for a literal backslash");out+=raw[i];}}else out+=c;}if(!closed)r.error(line,"","Unclosed quoted value");auto tail=trim(raw.substr(i));if(!tail.empty()&&tail[0]!=';'&&tail[0]!='#')r.error(line,"","Unexpected text after quoted value");return out;}for(size_t i=0;i<raw.size();++i)if((raw[i]==';'||raw[i]=='#')&&(i==0||raw[i-1]==' '||raw[i-1]=='\t'))return trim(raw.substr(0,i));return raw;}
std::vector<Entry> ini(const std::string& text,Report&r){std::istringstream in(text);std::string raw,section;std::vector<Entry> entries;std::unordered_set<std::string> keys,sections;size_t line=0;while(std::getline(in,raw)){++line;auto s=trim(raw);if(s.empty()||s[0]==';'||s[0]=='#')continue;if(s[0]=='['){auto end=s.find(']');if(end==std::string::npos){r.error(line,"","Section is missing a closing ]");continue;}section=trim(s.substr(1,end-1));auto tail=trim(s.substr(end+1));if(section.empty()||section.find('[')!=std::string::npos)r.error(line,section,"Section name is empty or contains [");if(!tail.empty()&&tail[0]!=';'&&tail[0]!='#')r.error(line,section,"Unexpected text after section heading");if(!sections.insert(section).second)r.error(line,section,"Duplicate section; merge it explicitly before migration");continue;}auto eq=s.find('=');if(eq==std::string::npos){r.error(line,"","Expected key=value");continue;}auto key=trim(s.substr(0,eq));if(key.empty()||key.find('[')!=std::string::npos||key.find(']')!=std::string::npos){r.error(line,key,"Key is empty or contains a bracket");continue;}auto source=section.empty()?key:"["+section+"]"+key;if(!keys.insert(source).second)r.error(line,source,"Duplicate key; implicit overrides are not allowed");auto value=decode_value(s.substr(eq+1),line,r);entries.push_back({source,value,line});if(entries.size()>50000)throw std::runtime_error("INI exceeds 50,000 entries");}if(entries.empty())r.error(0,"","INI contains no key=value entries");return entries;}
int main(int argc,char**argv){Report r;try{auto a=arguments(argc,argv);auto entries=ini(read_text(a.input),r);r.read=entries.size();std::unordered_map<std::string,Entry> values;for(auto&e:entries){r.fields.push_back(e.source);values.emplace(e.source,e);}if(a.inspect){r.print();return r.errors.empty()?0:2;}auto mapping=a.map.empty()?std::vector<Mapping>{}:read_map(a.map);if(mapping.empty())for(auto&e:entries)mapping.push_back({e.source,e.source,"string",false});std::unordered_set<std::string> selected;std::ostringstream out;out<<"{\n";for(size_t i=0;i<mapping.size();++i){auto&m=mapping[i];selected.insert(m.source);if(i)out<<",\n";out<<"  "<<jq(m.target)<<": ";auto p=values.find(m.source);if(p==values.end()){if(m.required)r.error(0,m.source,"Required source key is missing");else r.warnings.push_back("Optional source key is absent: "+m.source);out<<"null";}else out<<typed(p->second.value,m,p->second.line,r);}out<<"\n}\n";size_t omitted=0;for(auto&e:entries)if(!selected.count(e.source))++omitted;if(omitted)r.warnings.push_back(std::to_string(omitted)+" source key(s) are intentionally omitted by the mapping");if(r.errors.empty()){atomic_write(a.input,a.output,out.str());r.written=mapping.size();}}catch(const std::exception&e){r.error(0,"",e.what());}r.print();return r.errors.empty()?0:2;}
